package view;

import bus.admin.AdminCrudBUS;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTable;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.SwingWorker;
import javax.swing.table.DefaultTableModel;
import model.admin.AdminCrudModels.*;
import model.auth.AuthenticatedSession;
import view.component.UIStyle;

final class AdminCrudPanel extends JPanel {
    private final AuthenticatedSession session; private final String module; private final AdminCrudBUS bus=new AdminCrudBUS();
    private final JTextField search=new JTextField(); private final DefaultTableModel model=new DefaultTableModel(){public boolean isCellEditable(int r,int c){return false;}}; private final JTable table=new JTable(model); private final JButton edit=new JButton("Chỉnh sửa"); private final JButton delete=new JButton("Xóa");
    AdminCrudPanel(AuthenticatedSession s,String m){session=s;module=m;setLayout(new BorderLayout(0,16));setBackground(MainFrame.PAGE);setBorder(BorderFactory.createEmptyBorder(25,28,30,28));add(header(),BorderLayout.NORTH);add(body(),BorderLayout.CENTER);load();}
    private JPanel header(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);JPanel l=new JPanel();l.setOpaque(false);l.setLayout(new javax.swing.BoxLayout(l,javax.swing.BoxLayout.Y_AXIS));JLabel t=new JLabel(module);t.setFont(new java.awt.Font("Segoe UI",java.awt.Font.BOLD,25));t.setForeground(MainFrame.TEXT);JLabel d=new JLabel(description());d.setForeground(MainFrame.MUTED);l.add(t);l.add(javax.swing.Box.createVerticalStrut(5));l.add(d);JButton add=new JButton("+ Thêm mới");UIStyle.primaryButton(add);add.addActionListener(e->open(null));p.add(l,BorderLayout.WEST);p.add(add,BorderLayout.EAST);return p;}
    private String description(){return switch(module){case "Đánh giá nhân viên"->"Tạo, cập nhật và quản lý kết quả đánh giá nhân sự.";case "Cấu hình hệ thống"->"Quản lý tham số vận hành của phòng khám.";default->"Soạn, cập nhật và quản lý thông báo trong hệ thống.";};}
    private JPanel body(){JPanel card=new JPanel(new BorderLayout(0,12));card.setBackground(Color.WHITE);card.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(MainFrame.BORDER),BorderFactory.createEmptyBorder(16,16,16,16)));JPanel bar=new JPanel(new BorderLayout(8,0));bar.setOpaque(false);search.setPreferredSize(new Dimension(380,36));UIStyle.field(search);search.putClientProperty("JTextField.placeholderText","Tìm kiếm dữ liệu...");search.addActionListener(e->load());JPanel actions=new JPanel();actions.setOpaque(false);UIStyle.secondaryButton(edit);UIStyle.dangerButton(delete);edit.setEnabled(false);delete.setEnabled(false);edit.addActionListener(e->open(selected()));delete.addActionListener(e->remove());JButton refresh=new JButton("Làm mới");UIStyle.secondaryButton(refresh);refresh.addActionListener(e->load());actions.add(edit);actions.add(delete);actions.add(refresh);bar.add(search,BorderLayout.CENTER);bar.add(actions,BorderLayout.EAST);UIStyle.table(table);table.setAutoCreateRowSorter(true);table.getSelectionModel().addListSelectionListener(e->updateActions());card.add(bar,BorderLayout.NORTH);card.add(new JScrollPane(table),BorderLayout.CENTER);return card;}
    private void load(){new SwingWorker<List<?>,Void>(){protected List<?> doInBackground(){return switch(module){case "Đánh giá nhân viên"->bus.evaluations(session,search.getText());case "Cấu hình hệ thống"->bus.configs(session,search.getText());default->bus.notifications(session,search.getText());};}protected void done(){try{List<?> rows=get();model.setDataVector(new Object[0][columns().length],columns());for(Object row:rows)addRow(row);updateActions();}catch(Exception e){UIStyle.showError(AdminCrudPanel.this,message(e));}}}.execute();}
    private String[] columns(){return switch(module){case "Đánh giá nhân viên"->new String[]{"Mã","Nhân viên","Kỳ","Ngày","Điểm","Nhận xét"};case "Cấu hình hệ thống"->new String[]{"Mã cấu hình","Giá trị","Kiểu","Mô tả"};default->new String[]{"Mã","Tiêu đề","Loại","Trạng thái","Kênh gửi"};};}
    private void addRow(Object value){if(value instanceof Evaluation x)model.addRow(new Object[]{x.id(),x.employeeName(),x.period(),x.date(),x.score(),x.comment()});else if(value instanceof Config x)model.addRow(new Object[]{x.id(),x.value(),x.type(),x.description()});else if(value instanceof Notification x)model.addRow(new Object[]{x.id(),x.title(),x.type(),x.status(),x.channel()});}
    private Object selected(){int r=table.getSelectedRow();if(r<0)return null;String key=String.valueOf(model.getValueAt(table.convertRowIndexToModel(r),0));try{if(module.equals("Đánh giá nhân viên")){long id=Long.parseLong(key);return bus.evaluations(session,"").stream().filter(x->x.id()==id).findFirst().orElse(null);}if(module.equals("Thông báo")){long id=Long.parseLong(key);return bus.notifications(session,"").stream().filter(x->x.id()==id).findFirst().orElse(null);}return bus.configs(session,"").stream().filter(x->x.id().equals(key)).findFirst().orElse(null);}catch(Exception e){return null;}}
    private void updateActions(){boolean on=table.getSelectedRow()>=0;edit.setEnabled(on);delete.setEnabled(on);}
    private void open(Object existing){try{if(module.equals("Cấu hình hệ thống")){Config x=existing instanceof Config?(Config)existing:null;JTextField id=new JTextField(x==null?"":x.id()),value=new JTextField(x==null?"":safe(x.value())),type=new JTextField(x==null?"":safe(x.type())),desc=new JTextField(x==null?"":safe(x.description()));if(x!=null)id.setEditable(false);JPanel f=form(new String[]{"Mã cấu hình","Giá trị","Kiểu dữ liệu","Mô tả"},new JTextField[]{id,value,type,desc});if(ok(f,"Cấu hình hệ thống")){bus.saveConfig(session,new Config(id.getText(),value.getText(),type.getText(),desc.getText()));load();}return;}if(module.equals("Đánh giá nhân viên")){Evaluation x=existing instanceof Evaluation?(Evaluation)existing:null;JTextField employee=new JTextField(x==null?"":x.employeeId()),period=new JTextField(x==null?"":x.period()),date=new JTextField(x==null?LocalDate.now().toString():String.valueOf(x.date())),score=new JTextField(x==null?"":String.valueOf(x.score()==null?"":x.score())),comment=new JTextField(x==null?"":safe(x.comment()));JPanel f=form(new String[]{"Mã nhân viên","Kỳ đánh giá","Ngày (yyyy-MM-dd)","Điểm (0-10)","Nhận xét"},new JTextField[]{employee,period,date,score,comment});if(ok(f,"Đánh giá nhân viên")){bus.saveEvaluation(session,new EvaluationDraft(x==null?null:x.id(),employee.getText(),period.getText(),LocalDate.parse(date.getText()),score.getText().isBlank()?null:new BigDecimal(score.getText()),comment.getText()));load();}return;}Notification x=existing instanceof Notification?(Notification)existing:null;JTextField title=new JTextField(x==null?"":x.title()),type=new JTextField(x==null?"":safe(x.type())),channel=new JTextField(x==null?"":safe(x.channel())),employee=new JTextField(x==null?"":safe(x.employeeId())),patient=new JTextField(x==null?"":safe(x.patientId()));JTextArea content=new JTextArea(x==null?"":x.content(),5,30);JPanel f=new JPanel(new GridLayout(0,2,8,8));f.add(new JLabel("Tiêu đề"));f.add(title);f.add(new JLabel("Nội dung"));f.add(new JScrollPane(content));f.add(new JLabel("Loại"));f.add(type);f.add(new JLabel("Kênh gửi"));f.add(channel);f.add(new JLabel("Mã nhân viên"));f.add(employee);f.add(new JLabel("Mã bệnh nhân"));f.add(patient);if(ok(f,"Thông báo")){bus.saveNotification(session,new NotificationDraft(x==null?null:x.id(),employee.getText(),patient.getText(),title.getText(),content.getText(),type.getText(),x==null?"Nhap":x.status(),channel.getText()));load();}}catch(Exception e){UIStyle.showError(this,message(e));}}
    private JPanel form(String[] labels,JTextField[] fields){JPanel p=new JPanel(new GridLayout(0,2,8,8));for(int i=0;i<labels.length;i++){p.add(new JLabel(labels[i]));UIStyle.field(fields[i]);p.add(fields[i]);}return p;}
    private boolean ok(JPanel p,String title){return UIStyle.showFormDialog(this,p,"Thêm/chỉnh sửa "+title,new Dimension(520,360))==JOptionPane.OK_OPTION;}
    private void remove(){Object x=selected();if(x==null||JOptionPane.showConfirmDialog(this,"Bạn có chắc muốn xóa bản ghi này?","Xác nhận",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{if(x instanceof Evaluation e)bus.deleteEvaluation(session,e.id());else if(x instanceof Config c)bus.deleteConfig(session,c.id());else if(x instanceof Notification n)bus.deleteNotification(session,n.id());load();}catch(Exception e){UIStyle.showError(this,message(e));}}
    private static String safe(String x){return x==null?"":x;}private static String message(Exception e){Throwable c=e.getCause()==null?e:e.getCause();return c.getMessage()==null?"Không thể thực hiện thao tác.":c.getMessage();}
}
